function renderInspector(){$('#coreRegisters').innerHTML=registerRows(['WREG','STATUS','BSR']);$('#watchRegisters').innerHTML=registerRows(S.watches);const status=S.values.STATUS===undefined?null:parseInt(S.values.STATUS.replace(/^0x/i,''),16);$('#statusBits').innerHTML=['N','OV','Z','DC','C'].map((name,i)=>`<div class="bit ${status!==null&&(status>>(4-i)&1)?'on':''}">${name}<span>${status===null?'—':(status>>(4-i)&1)}</span></div>`).join('');$('#pcValue').textContent=S.location.address?S.location.address.toUpperCase().replace('0X','0x'):'—';$('#pcLocation').textContent=S.location.file?S.location.file.split('/').pop()+' : '+S.location.line:(S.debug==='disconnected'?'Start a session to inspect execution':'At reset vector');$('#breakpointCount').textContent=S.breakpoints.length;$('#breakpoints').className=S.breakpoints.length?'':'empty-small';$('#breakpoints').innerHTML=S.breakpoints.length?S.breakpoints.map((b,i)=>`<div class="bp-row"><span class="bp-dot">●</span><button data-bp-go="${i}">${esc(b.path.split('/').pop())}:${b.line}</button><button class="mini-icon" data-bp-delete="${i}" title="Remove breakpoint">×</button></div>`).join(''):'Click a line number or its left margin to set a breakpoint. Then press Continue (F5).';$$('[data-edit]').forEach(b=>b.onclick=()=>editRegister(b.dataset.edit));$$('[data-remove-watch]').forEach(b=>b.onclick=()=>{setWatches(S.watches.filter(n=>n!==b.dataset.removeWatch));});$$('[data-bp-go]').forEach(b=>b.onclick=()=>{const p=S.breakpoints[+b.dataset.bpGo];safeOpen(p.path,p.line);});$$('[data-bp-delete]').forEach(b=>b.onclick=()=>{const p=S.breakpoints[+b.dataset.bpDelete];toggleBreakpoint(p.path,p.line);});controls();}
