function applyInspection(data){if(data.state)S.debug=data.state;if(data.location)S.location=data.location;if(data.breakpoints)S.breakpoints=data.breakpoints;if(data.stopwatch)S.stopwatch=data.stopwatch;S.previous={...S.values};for(const r of data.registers||[])S.values[r.name]=r.value;renderInspector();updateMarks();}
