function addWatch(name){if(!name){showModal(`<h2>Add a watch</h2><p>Enter an SFR or an assembly symbol from your program.</p><input id="watchName" class="input" list="registerSuggestions" placeholder="e.g. LATD or count"><datalist id="registerSuggestions">${S.device.registers.map(r=>`<option>${esc(r.name)}</option>`).join('')}</datalist><div class="modal-actions"><button class="button" data-dismiss>Cancel</button><button id="watchAdd" class="button primary">Add watch</button></div>`);$('#watchAdd').onclick=()=>{const n=$('#watchName').value.trim();if(!/^[A-Za-z_][A-Za-z0-9_.$]*$/.test(n)){toast('Enter a register or symbol name.',true);return;}$('#modal').close();addWatch(n);};$('#watchName').focus();return;}if(!['WREG','STATUS','BSR'].includes(name))setWatches([...S.watches,name]);if(S.debug==='paused')task('Reading watch…',refreshRegisters);else toast(name+' added to Watches.');}
