function commandPalette(){const commands=[['Open project','open','⌘O'],['Create C or assembly project','new','⌘N'],['New source or header','addSource',''],['Import starter into current tab','importSource',''],['Export current source','exportSource',''],['Build project','build','⌘B'],['Save all files','saveAll','⇧⌘S'],['Start debugging','debug','⌘D'],['Program PICkit 3','program',''],['Clean project','clean',''],['Regenerate makefiles','regenerate',''],['Toolchain settings','settings','⌘,'],['Reveal project in Finder','reveal','']];showModal(`<input id="commandInput" class="input" placeholder="Search commands or open files…" aria-label="Search commands"><div class="modal-list" id="commandResults" style="margin-top:12px"></div>`);function results(q=''){const list=[...commands.map(([label,action,key])=>({label,action,key})),...(S.project?.files||[]).map(f=>({label:f.name,path:f.path,key:''}))].filter(c=>c.label.toLowerCase().includes(q.toLowerCase()));$('#commandResults').innerHTML=list.map((c,i)=>`<button class="command-item" data-command="${i}">${icon(c.path?'files':'arrow')}${esc(c.label)}<kbd>${c.key}</kbd></button>`).join('');$$('[data-command]').forEach(b=>b.onclick=()=>{const c=list[+b.dataset.command];$('#modal').close();c.path?safeOpen(c.path):actions[c.action]?.();});}results();$('#commandInput').oninput=e=>results(e.target.value);$('#commandInput').focus();}
window.asterEvent=(name,data)=>{
 if(name==='menu'){actions[data]?.();return;}
 if(name==='bridge'){bridgeEvent(data);return;}
 if(name==='bridgeState'){setBridge(data);return;}
 if(name==='buildStart'){S.output='';S.diagnostics=[];$('#problemCount').textContent='0';$('#cancelBuild').hidden=false;panel('output');}
 if(name==='buildOutput')log(data);
 if(name==='buildEnd'){$('#cancelBuild').hidden=true;S.diagnostics=data.diagnostics;$('#problemCount').textContent=S.diagnostics.length;if(S.project)S.project.outputs=data.outputs;renderSidebar();updateMarks();const label=data.ok?(data.clean?'Clean complete':`Build succeeded · ${data.elapsed.toFixed(2)}s`):'Build failed';$('#buildStatus').textContent=label;$('#buildStatus').className=data.ok?'good':'bad';log('\n'+label+'\n');if(!data.ok&&S.diagnostics.length)panel('problems');}
 if(name==='debugOutput'){S.debugOutput=(S.debugOutput+data).slice(-300000);if(S.panel==='debug')renderPanel();}
 if(name==='debugState'){S.debug=data.state;renderInspector();controls();if(S.panel==='interrupts')renderPanel();}
 if(name==='debugStopped'){S.debug='paused';S.location=data;renderInspector();updateMarks();$('#buildStatus').textContent='Paused · '+data.address;$('#buildStatus').className='good';if(!S.busy){refreshRegisters().catch(e=>toast(e.message,true));if(S.files.has(data.file)){showFile(data.file);E.go(data.line);}}}
 if(name==='ad2Frame'){if(data.run===S.ad2RunId)ad2Received(data.frame);return;}
 if(name==='ad2Stopped'){if(data.run===S.ad2RunId){S.ad2Running=false;ad2RunState();if(data.error)toast(data.error,true);}return;}
 if(name==='serialData'){S.serialOutput=(S.serialOutput+data).slice(-200000);if(data.includes('[Serial device disconnected]'))S.serial=false;if(S.panel==='serial')renderPanel();}
 if(name==='requestClose'){(async()=>{if([...S.files.values()].some(f=>f.dirty)){if(!await api('confirm',{title:'Quit with unsaved changes?',message:'Unsaved changes will be discarded. Cancel to save your files first.',accept:'Discard and Quit'}))return;}if(S.busy&&!await api('confirm',{title:'An operation is still running.',message:'Quit will stop active tools and disconnect the debugger.',accept:'Stop and Quit'}))return;await api('closeApproved');})();}
};
